import React, { useEffect, useState, useRef, useMemo } from "react";
import axios from "axios";
import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip
} from "react-leaflet";
import "leaflet/dist/leaflet.css";
import L from "leaflet";

import { Line } from "react-chartjs-2";
import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
} from "chart.js";

ChartJS.register(
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Legend
);

function App() {
  const [data, setData] = useState([]);
  const [path, setPath] = useState([]);

  const [index, setIndex] = useState(0);
  const [playing, setPlaying] = useState(false);

  const [speed, setSpeed] = useState(1);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  const [shouldZoom, setShouldZoom] = useState(false);

  const mapRef = useRef();

  const droneIcon = L.divIcon({
    html: `
      <div style="
        width:16px;
        height:16px;
        background:cyan;
        border-radius:50%;
        border:2px solid white;
        box-shadow:0 0 10px cyan;
      "></div>
    `,
    className: ""
  });
  const takeoffIcon = L.divIcon({
  html: `
    <div style="
      font-size:24px;
    ">
      🚀
    </div>
  `,
  className: ""
});

const landingIcon = L.divIcon({
  html: `
    <div style="
      font-size:24px;
    ">
      🛬
    </div>
  `,
  className: ""
});

  function computePointsPerSecond(records) {
    const bucket = {};

    records.forEach((p) => {
      const ts = new Date(p.timestamp);
      const key = Math.floor(ts.getTime() / 1000);

      bucket[key] = (bucket[key] || 0) + 1;
    });

    return {
      labels: Object.keys(bucket),
      values: Object.values(bucket)
    };
  }

  const fetchData = async () => {
    try {
      const res = await axios.get(
        "http://localhost:3000/path",
        {
          params: {
            start: startTime,
            end: endTime
          }
        }
      );

      const d = res.data;

      if (!d.length) {
        alert("No telemetry found");
        return;
      }

      setData(d);

      const coords = d.map((p) => ({
        lat: p.lat,
        lng: p.lon,
        alt: p.alt || 0,
        voltage: p.voltage || 0,
        timestamp: p.timestamp
      }));

      setPath(coords);

      setIndex(0);

      setShouldZoom(true);

      setPlaying(false);
    } catch (err) {
      console.error(err);
      alert("Failed to load telemetry");
    }
  };

  useEffect(() => {
    if (
      !shouldZoom ||
      !mapRef.current ||
      path.length === 0
    )
      return;

    const bounds = L.latLngBounds(
      path.map((p) => [p.lat, p.lng])
    );

    mapRef.current.fitBounds(bounds, {
      padding: [50, 50]
    });

    setShouldZoom(false);
  }, [shouldZoom, path]);

  useEffect(() => {
    if (!playing) return;

    if (index >= data.length - 1) return;

    const curr = new Date(
      data[index].timestamp
    );

    const next = new Date(
      data[index + 1].timestamp
    );

    const delay =
      Math.max(
        50,
        Math.min(next - curr, 1000)
      ) / speed;

    const timer = setTimeout(() => {
      setIndex((prev) => prev + 1);
    }, delay);

    return () => clearTimeout(timer);
  }, [playing, data, index, speed]);

  useEffect(() => {
    if (!mapRef.current) return;

    if (!path[index]) return;

    mapRef.current.flyTo(
      [path[index].lat, path[index].lng],
      18,
      {
        duration: 0.5
      }
    );
  }, [index, path]);

  const pps = useMemo(() => {
    return computePointsPerSecond(
      data.slice(0, index)
    );
  }, [data, index]);

  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        labels: {
          color: "white"
        }
      }
    },
    scales: {
      x: {
        ticks: {
          color: "white"
        }
      },
      y: {
        ticks: {
          color: "white"
        }
      }
    }
  };

  const altitudeChart = {
    labels: path
      .slice(0, index)
      .map((_, i) => i),

    datasets: [
      {
        label: "Altitude",
        data: path
          .slice(0, index)
          .map((p) => p.alt),
        borderColor: "cyan",
        tension: 0.3
      },
      {
        label: "Battery",
        data: path
          .slice(0, index)
          .map((p) => p.voltage),
        borderColor: "yellow",
        tension: 0.3
      }
    ]
  };

  const ppsChart = {
    labels: pps.labels,

    datasets: [
      {
        label: "Points / Second",
        data: pps.values,
        borderColor: "lime",
        tension: 0.3
      }
    ]
  };

  const maxAltitude =
    data.length > 0
      ? Math.max(
          ...data.map((x) => x.alt || 0)
        )
      : 0;

  const minVoltage =
    data.length > 0
      ? Math.min(
          ...data.map(
            (x) => x.voltage || 999
          )
        )
      : 0;

  const duration =
    data.length > 1
      ? (
          (new Date(
            data[data.length - 1]
              .timestamp
          ) -
            new Date(
              data[0].timestamp
            )) /
          1000
        ).toFixed(0)
      : 0;

  return (
    <div
      style={{
        background: "#000",
        color: "#fff",
        minHeight: "100vh",
        padding: "10px"
      }}
    >
      <h2>🚁 Drone Flight Dashboard</h2>

      <div
        style={{
          marginBottom: 10
        }}
      >
        Start:

        <input
          type="datetime-local"
          onChange={(e) =>
            setStartTime(
              new Date(
                e.target.value
              ).toISOString()
            )
          }
        />

        End:

        <input
          type="datetime-local"
          onChange={(e) =>
            setEndTime(
              new Date(
                e.target.value
              ).toISOString()
            )
          }
        />

        <button onClick={fetchData}>
          Load Flight
        </button>
      </div>

      <div
        style={{
          marginBottom: 10
        }}
      >
        <button
          onClick={() => setPlaying(true)}
        >
          ▶ Play
        </button>

        <button
          onClick={() =>
            setPlaying(false)
          }
        >
          ⏸ Pause
        </button>

        <button onClick={() => setSpeed(1)}>
          1x
        </button>

        <button onClick={() => setSpeed(2)}>
          2x
        </button>

        <button onClick={() => setSpeed(5)}>
          5x
        </button>

        <button onClick={() => setSpeed(10)}>
          10x
        </button>
      </div>

      <div
        style={{
          display: "flex",
          gap: "25px",
          background: "#111",
          padding: "10px",
          marginBottom: "10px"
        }}
      >
        <div>
          Alt:
          <br />
          {path[index]?.alt?.toFixed(2)}m
        </div>

        <div>
          Battery:
          <br />
          {path[index]?.voltage?.toFixed(2)}V
        </div>

        <div>
          Pitch:
          <br />
          {data[index]?.pitch?.toFixed(2)}
        </div>

        <div>
          Roll:
          <br />
          {data[index]?.roll?.toFixed(2)}
        </div>

        <div>
          Yaw:
          <br />
          {data[index]?.yaw?.toFixed(2)}
        </div>

        <div>
          Point:
          <br />
          {index}/{data.length}
        </div>
      </div>

      <MapContainer
        center={[12.97, 77.59]}
        zoom={13}
        style={{
          height: "60vh"
        }}
        whenCreated={(map) =>
          (mapRef.current = map)
        }
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        <Polyline
          positions={path.map((p) => [
            p.lat,
            p.lng
          ])}
          color="gray"
          weight={2}
        />

        <Polyline
          positions={path
            .slice(0, index)
            .map((p) => [
              p.lat,
              p.lng
            ])}
          color="cyan"
          weight={4}
        />

        {path.length > 0 && (
          <Marker
            position={[
              path[0].lat,
              path[0].lng
            ]}
          >
            <Tooltip>
              🚀 Takeoff
            </Tooltip>
          </Marker>
        )}

        {path.length > 0 && (
          <Marker
            position={[
              path[path.length - 1].lat,
              path[path.length - 1].lng
            ]}
          >
            <Tooltip>
              🛬 Landing
            </Tooltip>
          </Marker>
        )}

        {path[index] && (
          <Marker
            position={[
              path[index].lat,
              path[index].lng
            ]}
            icon={droneIcon}
          >
            <Tooltip>
              Alt:
              {" "}
              {path[index].alt}
              m
              <br />
              Battery:
              {" "}
              {path[index].voltage}
              V
            </Tooltip>
          </Marker>
        )}
      </MapContainer>

      <div
        style={{
          height: "250px",
          background: "#111",
          marginTop: "10px"
        }}
      >
        <Line
          data={altitudeChart}
          options={chartOptions}
        />
      </div>

      <div
        style={{
          height: "250px",
          background: "#111",
          marginTop: "10px"
        }}
      >
        <Line
          data={ppsChart}
          options={chartOptions}
        />
      </div>

      <div
        style={{
          background: "#111",
          padding: "15px",
          marginTop: "10px"
        }}
      >
        <h3>Flight Summary</h3>

        <div>
          Max Altitude:
          {" "}
          {maxAltitude.toFixed(2)} m
        </div>

        <div>
          Lowest Battery:
          {" "}
          {minVoltage.toFixed(2)} V
        </div>

        <div>
          Duration:
          {" "}
          {duration}
          s
        </div>

        <div>
          Total Points:
          {" "}
          {data.length}
        </div>
      </div>
    </div>
  );
}

export default App;
